using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using OfficeX.Core;
using Newtonsoft.Json.Linq;

var tests=new (string,Action)[] {
    ("no selection context uses active worksheet and detects worksheet switches before writing",()=>{var p=new FakeCellPort{ActiveSheet="second"};var session=new OfficeAutomationSession(p);var plan=ExcelCellWrites.Prepare(session,JObject.Parse("{operations:[{address:'A1',value:42}]}"),null);Equal("second",p.Sheet);p.ActiveSheet="third";Equal("conflict",session.Apply(plan.Id,true,default).Status);Equal(0,p.Writes);}),
    ("general cell writes preserve existing content intent and literal formula-looking text",()=>{var p=new FakeCellPort();p.Value="old";var session=new OfficeAutomationSession(p);var plan=ExcelCellWrites.Prepare(session,JObject.Parse("{operations:[{address:'Z20',value:'=1+1'}]}"),"내역");Equal("old",p.Value);Equal("verified",session.Apply(plan.Id,true,default).Status);Equal("=1+1",p.Value);Equal(false,p.HasFormula);Equal("General",p.Format);Equal("내역",p.Sheet);}),
    ("general formulas accept SUM and normalize function case without changing string literals",()=>{var p=new FakeCellPort();var session=new OfficeAutomationSession(p);var plan=ExcelCellWrites.Prepare(session,JObject.Parse("{operations:[{address:'B4',formula:'=sum(A1:A3)'}]}"),null);Equal("verified",session.Apply(plan.Id,true,default).Status);Equal(true,p.HasFormula);p.CorruptLiteral=true;plan=ExcelCellWrites.Prepare(session,JObject.Parse("{operations:[{address:'B4',formula:'=IF(A1=1,\"Yes\",\"No\")'}]}"),null);Equal("partial",session.Apply(plan.Id,true,default).Status);}),
    ("cell writes source drift approval decline and readback mismatch prevent completion",()=>{foreach(var mode in new[]{"drift","decline","corrupt"}){var p=new FakeCellPort();var session=new OfficeAutomationSession(p);var plan=ExcelCellWrites.Prepare(session,JObject.Parse("{operations:[{address:'A1',value:42}]}"),null);if(mode=="drift")p.Value=99d;p.CorruptValue=mode=="corrupt";var r=session.Apply(plan.Id,mode!="decline",default);Equal(false,r.Status=="verified");Equal(mode=="corrupt",p.Writes>0);Fault("invalid_plan",()=>session.Apply(plan.Id,true,default));}}),
    ("cell value batches support numeric boolean and null with fresh native reads",()=>{var p=new FakeCellPort();var session=new OfficeAutomationSession(p);foreach(var value in new JToken[]{new JValue(3.5),new JValue(true),JValue.CreateNull()}){var plan=ExcelCellWrites.Prepare(session,new JObject{["operations"]=new JArray(new JObject{["address"]="A1",["value"]=value})},null);Equal("verified",session.Apply(plan.Id,true,default).Status);}Equal(3,p.Writes);}),
    ("cell validation rejects malformed destinations and ambiguous payloads before reading",()=>{foreach(var json in new[]{"{operations:[{address:'A1:A2',value:1}]}","{operations:[{address:'A1',value:1,formula:'=1'}]}","{operations:[{address:'A1',value:1},{address:'A1',value:2}]}","{operations:[{address:'A1',value:{x:1}}]}"}){var p=new FakeCellPort();try{ExcelCellWrites.Prepare(new OfficeAutomationSession(p),JObject.Parse(json),null);throw new Exception("accepted invalid input");}catch(OfficeFault e){Equal(false,e.InvocationStarted);}Equal(0,p.Reads);}}),
    ("formula comparer is not available for arbitrary data readback",()=>{var p=new FakeAutomationPort();var session=new OfficeAutomationSession(p);var before=session.Inspect(OfficeReads());var checks=OfficeChecks("NEW");checks[0].Compare="excel_formula";Fault("office_check_compare_invalid",()=>session.Prepare(before.SnapshotId,"输入",OfficeWrites("new"),checks));Equal(0,p.Writes);}),

    ("Excel creation preserves multiline cells and pads only missing trailing cells",()=>{var p=new FakeCreationPort();var draft=new DocumentDraft{Title="업무 현황",Sheets=new List<SheetContent>{new SheetContent{Name="현황",Rows=new List<List<string>>{new List<string>{"담당","설명","비고"},new List<string>{"누비","첫 줄\r\n둘째 줄\t정리"},new List<string>{"합계"}}}}};var original=Wire.Json(draft);var creation=new DocumentCreation(p,"excel",draft);Equal(original,Wire.Json(draft));Equal(3,creation.Plan.Content.Sheets[0].Rows[1].Count);Equal("",creation.Plan.Content.Sheets[0].Rows[2][2]);Equal("첫 줄\r\n둘째 줄\t정리",creation.Plan.Content.Sheets[0].Rows[1][1]);Equal("verified",creation.Apply(creation.Plan.Id,true,default).Status);Equal(1,p.Creates);}),
    ("Excel rectangular validation uses the longest row rather than the first row",()=>{var draft=new DocumentDraft{Title="매출",Sheets=new List<SheetContent>{new SheetContent{Name="매출",Rows=new List<List<string>>{new List<string>{"매출"},new List<string>{"상품","금액"},new List<string>{"A","1000"}}}}};DocumentCreation.Validate("excel",draft);var creation=new DocumentCreation(new FakeCreationPort(),"excel",draft);Equal(2,creation.Plan.Content.Sheets[0].Rows[0].Count);Equal("",creation.Plan.Content.Sheets[0].Rows[0][1]);}),
    ("Excel invalid content returns a precise pre-write location without exposing cell data",()=>{var p=new FakeCreationPort();var draft=new DocumentDraft{Title="매출",Sheets=new List<SheetContent>{new SheetContent{Name="매출",Rows=new List<List<string>>{new List<string>{"담당","설명"},new List<string>{"누비","private\0data"}}}}};try{new DocumentCreation(p,"excel",draft);throw new Exception("Expected validation failure");}catch(OfficeFault e){Equal("document_content_invalid",e.Message);Equal(false,e.InvocationStarted);Equal("sheets[0].rows[1][1]",e.InputPath);Equal("unsupported_control_character",e.InputRule);Equal(false,Wire.Json(new{e.Message,e.InputPath,e.InputRule}).Contains("private"));}Equal(0,p.Creates);}),
    ("Excel normalization retains width and size limits and duplicate-name checks",()=>{var draft=new DocumentDraft{Title="x",Sheets=new List<SheetContent>{new SheetContent{Name="data",Rows=new List<List<string>>{new List<string>{"title"},Enumerable.Repeat("x",21).ToList()}}}};Fault("document_content_invalid",()=>DocumentCreation.Validate("excel",draft));draft.Sheets[0].Rows[1]=new List<string>{new string('x',2001)};Fault("document_content_invalid",()=>DocumentCreation.Validate("excel",draft));draft.Sheets[0].Rows[1]=new List<string>{"ok"};draft.Sheets.Add(new SheetContent{Name="DATA",Rows=new List<List<string>>{new List<string>{"x"}}});Fault("document_content_invalid",()=>DocumentCreation.Validate("excel",draft));}),
    ("generic native failures preserve member HRESULT and execution stage without claiming cell values",()=>{var p=new FakeAutomationPort{WriteFault=new System.Runtime.InteropServices.COMException("private workbook data",unchecked((int)0x80028018))};var session=new OfficeAutomationSession(p);var before=session.Inspect(OfficeReads());var plan=session.Prepare(before.SnapshotId,"입력",OfficeWrites("new"),OfficeChecks("new"));var r=session.Apply(plan.Id,true,default);Equal("native_execution_failed",r.Error);Equal("Text",r.FailedMember);Equal("COMException",r.ExceptionName);Equal("execute_step",r.FailureStage);Equal("0x80028018",r.NativeCode);Equal(0,r.CompletedWrites);Equal(true,r.WriteResultUncertain);Equal(false,Wire.Json(r).Contains("private workbook data"));}),

    ("read accessors before an unsupported write never count as completed document writes",()=>{var p=new FakeAutomationPort{WriteFault=new OfficeFault("office_member_not_found","Formula2",unchecked((int)0x80020003),false)};var session=new OfficeAutomationSession(p);var before=session.Inspect(OfficeReads());var steps=new List<OfficeStep>{new OfficeStep{Target="document",Action="call",Member="Item",Args=new JArray(1)}};steps.AddRange(OfficeWrites("new"));var plan=session.Prepare(before.SnapshotId,"값 입력",steps,OfficeChecks("new"));var receipt=session.Apply(plan.Id,true,default);Equal(0,receipt.CompletedWrites);Equal(false,receipt.Mutated);Equal(true,OfficeCallPolicy.CanReplan(receipt));Equal("original",p.Text);}),
    ("synchronous Office callers retain their owning thread without a UI synchronization context",()=>{var original=SynchronizationContext.Current;SynchronizationContext.SetSynchronizationContext(null);try{var port=new ThreadBoundAutomationPort();var session=new OfficeAutomationSession(port);var before=session.Inspect(OfficeReads());var plan=session.Prepare(before.SnapshotId,"입력",OfficeWrites("new"),OfficeChecks("new"));Equal("verified",session.Apply(plan.Id,true,default).Status);Equal("new",port.Inner.Text);}finally{SynchronizationContext.SetSynchronizationContext(original);}}),
    ("native task-pane review and receipt preserve the camelCase wire contract",()=>{
      var draft=new DocumentDraft{Title="매출",Sheets=new List<SheetContent>{new SheetContent{Name="매출",Rows=new List<List<string>>{new List<string>{"품목","금액"},new List<string>{"샘플","1000"}}}}};
      var review=Wire.Object(new{type="review",runId="native-run",planId="native-plan",plan=new CreationPlan{Id="native-plan",App="excel",Content=draft}});
      var transmitted=JObject.Parse(Wire.Json(review));Equal("create_document",(string)transmitted["plan"]["kind"]);Equal("매출",(string)transmitted["plan"]["content"]["sheets"][0]["name"]);Equal(null,transmitted["plan"]["Kind"]);
      var receipt=Wire.Object(new{type="receipt",runId="native-run",receipt=new CreationReceipt{Status="verified",Mutated=true,Count=1}});Equal("verified",(string)receipt["receipt"]["status"]);Equal(true,(bool)receipt["receipt"]["mutated"]);
      var context=Wire.Object(new Snapshot{Workbook="통합문서",Address="A1"});Equal("통합문서",(string)context["workbook"]);
      var operation=Wire.Object(new{plan=new OfficePlan{Steps=new List<OfficeStep>{new OfficeStep{Action="set",Member="Text",Value="값"}}}});Equal("Text",(string)operation["plan"]["steps"][0]["member"]);
      var packets=new List<object>();foreach(var app in new[]{"excel","word","powerpoint"}){
        var content=app=="excel"?draft:app=="word"?new DocumentDraft{Title="보고서",Paragraphs=new List<DocumentPart>{new DocumentPart{Style="Title",Text="보고서"}}}:new DocumentDraft{Title="발표",Slides=new List<SlideContent>{new SlideContent{Title="목적",Body=new List<string>{"업무 개선"}}}};
        packets.Add(new{app,review=Wire.Object(new{type="review",runId="native-run",planId="native-plan",target=app,plan=new CreationPlan{Id="native-plan",App=app,Content=content}}),receipt=Wire.Object(new{type="receipt",runId="native-run",receipt=new CreationReceipt{PlanId="native-plan",Status="verified",Mutated=true,Document="새 문서",Count=1}})});
      }System.IO.Directory.CreateDirectory("verification");System.IO.File.WriteAllText("verification/native-wire.json",Wire.Json(packets));
    }),
    ("unsupported member before invocation can be replanned without reporting a write",()=>{var p=new FakeAutomationPort{WriteFault=new OfficeFault("office_member_not_found","Formula2",unchecked((int)0x80020003),false)};var s=new OfficeAutomationSession(p);var read=s.Inspect(OfficeReads());var plan=s.Prepare(read.SnapshotId,"입력",OfficeWrites("new"),OfficeChecks("new"));var r=s.Apply(plan.Id,true,default);Equal(false,r.Mutated);Equal(0,p.Writes);Equal(true,OfficeCallPolicy.CanReplan(r));Fault("invalid_plan",()=>s.Apply(plan.Id,true,default));p.WriteFault=null;read=s.Inspect(OfficeReads());plan=s.Prepare(read.SnapshotId,"지원 멤버로 입력",OfficeWrites("new"),OfficeChecks("new"));Equal("verified",s.Apply(plan.Id,true,default).Status);Equal(1,p.Writes);}),
    ("real partial writes cannot be replanned as an unsupported-member retry",()=>{var r=new OfficeExecutionReceipt{Error="office_member_not_found",Status="partial",Mutated=true,CompletedWrites=1};Equal(false,OfficeCallPolicy.CanReplan(r));}),
    ("property paths preserve read and mutation classification without execution escapes",()=>{
      foreach(var member in new[]{"Font.Bold","Interior.Color","Content.Font.Size","TextFrame.TextRange.Text"}){Equal(true,OfficeCallPolicy.Exposed(member));OfficeCallPolicy.Validate(member,false,"set");Equal(true,OfficeCallPolicy.WritesDocument(new OfficeStep{Member=member,Action="set"}));}
      foreach(var member in new[]{"Font","Count","Value2","Font.Bold","TextFrame.TextRange.Text"}){OfficeCallPolicy.Validate(member,true,"call");Equal(true,OfficeCallPolicy.ReadCall(member));Equal(false,OfficeCallPolicy.WritesDocument(new OfficeStep{Member=member,Action="call"}));Equal(false,OfficeCallPolicy.MethodAccessor(member));}
      Equal(true,OfficeCallPolicy.ReadCall("Worksheets.Item"));Equal(false,OfficeCallPolicy.WritesDocument(new OfficeStep{Member="Worksheets.Item",Action="call"}));
      foreach(var member in new[]{"Font.Application.Name","Parent.Font.Bold","Font.AddPicture","Font.SaveAs"}){Equal(false,OfficeCallPolicy.Exposed(member));Fault("office_member_unavailable",()=>OfficeCallPolicy.Validate(member,false,"set"));}
      foreach(var member in new[]{"Font..Bold","Range(1).Value2","Font.Bold()","Font.[Bold]",".Font.Bold","Font.Bold."}){Fault("office_member_path_not_supported",()=>OfficeCallPolicy.Validate(member,false,"set"));}
      Fault("office_read_requires_get",()=>OfficeCallPolicy.Validate("Rows.AutoFit",true,"call"));
    }),
    ("removed image creation cannot be called through native Office members",()=>{foreach(var member in new[]{"AddPicture","AddPicture2","AddMediaObject","AddIcon","UserPicture"}){Equal(false,OfficeCallPolicy.Exposed(member));Fault("office_member_unavailable",()=>OfficeCallPolicy.Validate(member,false,"call"));}Equal(true,OfficeCallPolicy.Exposed("AddShape"));}),
    ("model execution escape remains unavailable and metadata errors are not write successes",()=>{Equal(false,OfficeCallPolicy.Exposed("Application"));Equal(false,OfficeCallPolicy.Exposed("Run"));Equal(true,OfficeCallPolicy.BeforeInvocation(unchecked((int)0x80020006)));Equal(false,OfficeCallPolicy.BeforeInvocation(unchecked((int)0x800A03EC)));}),
    ("type library failure before invocation reports no completed write",()=>{var p=new FakeAutomationPort{WriteFault=new OfficeFault("office_operation_failed","Value2",unchecked((int)0x80028018),false)};var session=new OfficeAutomationSession(p);var before=session.Inspect(OfficeReads());var plan=session.Prepare(before.SnapshotId,"값 입력",OfficeWrites("new"),OfficeChecks("new"));var r=session.Apply(plan.Id,true,default);Equal("conflict",r.Status);Equal(false,r.Mutated);Equal(false,r.WriteResultUncertain);Equal(0,r.CompletedWrites);Equal("0x80028018",r.NativeCode);Equal("original",p.Text);}),
    ("Excel rejection reports unverified attempt instead of entered values",()=>{var p=new FakeAutomationPort{WriteFault=new OfficeFault("office_operation_failed","Formula",unchecked((int)0x800A03EC))};var session=new OfficeAutomationSession(p);var before=session.Inspect(OfficeReads());var plan=session.Prepare(before.SnapshotId,"수식 입력",OfficeWrites("new"),OfficeChecks("new"));var r=session.Apply(plan.Id,true,default);Equal("partial",r.Status);Equal(true,r.WriteResultUncertain);Equal(0,r.CompletedWrites);Equal("0x800A03EC",r.NativeCode);Equal("original",p.Text);Fault("writes_stopped_for_this_run",()=>session.Prepare(before.SnapshotId,"again",OfficeWrites("new"),OfficeChecks("new")));}),

    ("automatic shape resize preserves other text block checks",()=>{var(p,s,plan)=BatchSetup();p.AutoResize=true;Equal("verified",s.Apply(plan.Id,true,default).Status);}),
    ("shape geometry drift before approval blocks replacement",()=>{var(p,s,plan)=BatchSetup();p.Data.Blocks[0].SourceLayoutHash="user resized";Equal("conflict",s.Apply(plan.Id,true,default).Status);Equal(0,p.Writes);}),
