    ("minimal splice preserves unchanged prefix and suffix including emoji",()=>{foreach(var pair in new[]{("bold original suffix","bold revised suffix"),("a😀z","a😁z"),("", "빈 문단 작성"),("same","same"),("prefix","prefix plus"),("abc","ac")}){var e=TextSplice.Between(pair.Item1,pair.Item2);Equal(pair.Item2,pair.Item1.Substring(0,e.Start)+e.Text+pair.Item1.Substring(e.Start+e.Length));if(e.Start<pair.Item1.Length)Equal(false,char.IsLowSurrogate(pair.Item1[e.Start]));}}),

